    }

    private BigDecimal calcularPesoTotal(List<Item> itens) {
        BigDecimal peso = BigDecimal.ZERO;
        for (Item item : itens) {
            peso = peso.add(item.getPesoKg().multiply(new BigDecimal(item.getQuantidade())));
        }
